Task: Put the red cube into the red tray and the blue cube into the blue tray.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """Sort cubes by colour into matching trays."""
  5|     robot.home()
  6| 
  7|     # Get current scene description
  8|     obs = robot.observe()
  9| 
 10|     # Separate cubes and trays
 11|     cubes = {name: obj for name, obj in obs['objects'].items() if obj['shape'] == 'cube'}
 12|     trays = {name: fix for name, fix in obs['fixtures'].items() if fix['kind'] == 'tray'}
 13| 
 14|     # Map colour -> tray name (e.g., 'red' -> 'red_tray')
 15|     colour_to_tray = {}
 16|     for name, fix in trays.items():
 17|         colour_to_tray[fix['color']] = name
 18| 
 19|     overall_success = True
 20| 
 21|     for cube_name, cube in cubes.items():
 22|         colour = cube['color']
 23|         tray_name = colour_to_tray.get(colour)
 24|         if tray_name is None:
 25|             robot.log(f"No tray found for colour '{colour}'")
 26|             overall_success = False
 27|             continue
 28| 
 29|         # Get up-to-date poses (perception is noisy)
 30|         cube_pose = robot.get_pose(cube_name)
 31|         tray_pose = robot.get_pose(tray_name)
 32| 
 33|         if not _pick_and_place(robot, cube_pose, tray_pose):
 34|             robot.log(f"Failed to place {cube_name} into {tray_name}")
 35|             overall_success = False
 36| 
 37|     return overall_success
 38| 
 39| 
 40| def _pick_and_place(robot, cube_pose, tray_pose):
 41|     """Attempt one pick‑and‑place cycle. Returns True on success."""
 42|     max_attempts = 2
 43|     lift_height = 0.10          # safe travel height above the table
 44|     grasp_offset = 0.02         # how far above the cube centre we close the fingers
 45|     place_offset = 0.02         # how far above the tray bottom we release
 46| 
 47|     for attempt in range(max_attempts):
 48|         try:
 49|             # 1. Move above the cube
 50|             above_cube = [cube_pose['pos'][0], cube_pose['pos'][1], lift_height]
 51|             robot.move_to(*above_cube, speed=0.2)
 52| 
 53|             # 2. Descend to a grasp height (just above the cube centre)
 54|             grasp_z = cube_pose['pos'][2] + grasp_offset
 55|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], grasp_z,
 56|                           speed=0.05)
 57| 
 58|             # 3. Close fingers
 59|             if not robot.grasp():
 60|                 robot.release()  # ensure hand is open before retrying
 61|                 continue
 62| 
 63|             # 4. Verify we actually hold something
 64|             if robot.holding() is None:
 65|                 robot.release()
 66|                 continue
 67| 
 68|             # 5. Lift the cube
 69|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], lift_height,
 70|                           speed=0.05)
 71| 
 72|             # 6. Move above the target tray
 73|             above_tray = [tray_pose['pos'][0], tray_pose['pos'][1], lift_height]
 74|             robot.move_to(*above_tray, speed=0.2)
 75| 
 76|             # 7. Lower to just above the tray bottom
 77|             place_z = tray_pose['pos'][2] + place_offset
 78|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], place_z,
 79|                           speed=0.05)
 80| 
 81|             # 8. Release the cube
 82|             robot.release()
 83|             robot.wait(0.05)  # brief pause to let the object settle
 84| 
 85|             # 9. Retract to safe height
 86|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], lift_height,
 87|                           speed=0.05)
 88| 
 89|             return True  # success for this cube
 90| 
 91|         except Exception as e:  # catches MotionError and other unexpected issues
 92|             robot.log(f"Attempt {attempt+1} failed: {e}")
 93|             robot.release()  # try to leave the hand open
 94|             continue
 95| 
 96|     # If we exit the loop, all attempts failed
 97|     return False

